import type { FastifyInstance } from 'fastify';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { makeTestApp } from '../helpers/app.js';

// Generated by monopoly-slice from the plan; /monopoly-kit:feature-tests adds the domain-specific cases.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const UNKNOWN_ID = '00000000-0000-4000-8000-000000000000';

let app: FastifyInstance;
let refs: { ownerId: string };

beforeEach(async () => {
  app = makeTestApp().app;
  const owner = await app.inject({ method: 'POST', url: '/players', payload: { name: 'Alice', token: 'car' } });
  expect(owner.statusCode).toBe(201);
  refs = { ownerId: owner.json().id };
});

afterEach(async () => {
  await app.close();
});

const valid = (i: 1 | 2 = 1) => (i === 1 ? { name: 'Alpha', colorGroup: 'brown', price: 1, rent: 0, ownerId: refs.ownerId } : { name: 'Bravo', colorGroup: 'light-blue', price: 2, rent: 1, ownerId: refs.ownerId });

function create(payload: object) {
  return app.inject({ method: 'POST', url: '/properties', payload });
}

async function createOk(payload: object = valid()) {
  const res = await create(payload);
  expect(res.statusCode).toBe(201);
  return res.json();
}

function patch(id: string, payload: object) {
  return app.inject({ method: 'PATCH', url: `/properties/${id}`, payload });
}

function expectError(res: { statusCode: number; json(): unknown }, status: number, code: string) {
  expect(res.statusCode).toBe(status);
  expect(res.json()).toEqual({ error: { code, message: expect.any(String) } });
}

describe('POST /properties', () => {
  it('creates a property', async () => {
    const res = await create(valid());
    expect(res.statusCode).toBe(201);
    const body = res.json();
    expect(body).toEqual({ ...valid(), id: expect.stringMatching(UUID), createdAt: expect.any(String) });
    expect(new Date(body.createdAt).toISOString()).toBe(body.createdAt);
  });

  it('creates a property without ownerId', async () => {
    const payload: Record<string, unknown> = valid();
    delete payload.ownerId;
    expect((await createOk(payload)).ownerId).toBeNull();
  });

  it('trims name', async () => {
    expect((await createOk({ ...valid(), name: '  Alpha  ' })).name).toBe('Alpha');
  });

  it('accepts 40 characters of name, counted as code points', async () => {
    await createOk({ ...valid(), name: '🎲'.repeat(40) });
  });

  it.each(['name', 'colorGroup', 'price', 'rent'])('rejects a body without %s with 400', async (key) => {
    const payload: Record<string, unknown> = valid();
    delete payload[key];
    expectError(await create(payload), 400, 'invalid');
  });

  it('rejects an unknown field with 400', async () => {
    expectError(await create({ ...valid(), nope: 1 }), 400, 'invalid');
  });

  it.each([
    ['empty name', { name: '' }],
    ['blank name', { name: '   ' }],
    ['41-character name', { name: 'a'.repeat(41) }],
    ['unknown colorGroup', { colorGroup: 'nope' }],
    ['price below 1', { price: 0 }],
    ['fractional price', { price: 1.5 }],
    ['price above 400', { price: 401 }],
    ['rent below 0', { rent: -1 }],
    ['fractional rent', { rent: 0.5 }],
    ['non-uuid ownerId', { ownerId: 'nope' }],
    ['unknown ownerId', { ownerId: UNKNOWN_ID }],
  ])('rejects %s with 400', async (_, over) => {
    expectError(await create({ ...valid(), ...over }), 400, 'invalid');
  });

  it('rejects a duplicate name with 409, in any case and padded', async () => {
    await createOk();
    expectError(await create({ ...valid(2), name: 'Alpha' }), 409, 'conflict');
    expectError(await create({ ...valid(2), name: 'ALPHA' }), 409, 'conflict');
    expectError(await create({ ...valid(2), name: ' alpha ' }), 409, 'conflict');
  });
});

describe('GET /properties', () => {
  it('returns an empty list', async () => {
    const res = await app.inject({ method: 'GET', url: '/properties' });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual([]);
  });

  it('returns every property', async () => {
    const a = await createOk(valid(1));
    const b = await createOk(valid(2));
    const res = await app.inject({ method: 'GET', url: '/properties' });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toHaveLength(2);
    expect(res.json()).toEqual(expect.arrayContaining([{ ...a, ownerName: 'Alice' }, { ...b, ownerName: 'Alice' }]));
  });

  it('returns ownerName null for an unowned deed', async () => {
    const a = await createOk({ ...valid(), ownerId: null });
    const res = await app.inject({ method: 'GET', url: '/properties' });
    expect(res.json()).toEqual([{ ...a, ownerName: null }]);
  });
});

describe('GET /properties/:id', () => {
  it('returns the property', async () => {
    const a = await createOk();
    const res = await app.inject({ method: 'GET', url: `/properties/${a.id}` });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual({ ...a, ownerName: 'Alice' });
  });

  it('returns ownerName null for an unowned deed', async () => {
    const a = await createOk({ ...valid(), ownerId: null });
    const res = await app.inject({ method: 'GET', url: `/properties/${a.id}` });
    expect(res.json()).toEqual({ ...a, ownerName: null });
  });

  it('reads ownerName from lobby, so a renamed player shows the new name', async () => {
    const a = await createOk();
    const renamed = await app.inject({ method: 'PATCH', url: `/players/${refs.ownerId}`, payload: { name: 'Alicia' } });
    expect(renamed.statusCode).toBe(200);
    const res = await app.inject({ method: 'GET', url: `/properties/${a.id}` });
    expect(res.json().ownerName).toBe('Alicia');
  });

  it('answers 404 for an unknown id', async () => {
    expectError(await app.inject({ method: 'GET', url: `/properties/${UNKNOWN_ID}` }), 404, 'not_found');
  });

  it('answers 400 for a non-uuid id', async () => {
    expectError(await app.inject({ method: 'GET', url: '/properties/nope' }), 400, 'invalid');
  });
});

describe('PATCH /properties/:id', () => {
  it('updates every field', async () => {
    const a = await createOk(valid(1));
    const changes = valid(2);
    const res = await patch(a.id, changes);
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual({ ...a, ...changes });
    const got = await app.inject({ method: 'GET', url: `/properties/${a.id}` });
    expect(got.json()).toEqual({ ...a, ...changes, ownerName: 'Alice' });
  });

  it('updates name and keeps the rest', async () => {
    const a = await createOk();
    const res = await patch(a.id, { name: 'Bravo' });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual({ ...a, name: 'Bravo' });
  });

  it('trims name', async () => {
    const a = await createOk();
    expect((await patch(a.id, { name: '  Bravo  ' })).json().name).toBe('Bravo');
  });

  it('clears ownerId with null', async () => {
    const a = await createOk();
    expect((await patch(a.id, { ownerId: null })).json().ownerId).toBeNull();
  });

  it("transfers the deed to another player's id", async () => {
    const a = await createOk();
    const bob = await app.inject({ method: 'POST', url: '/players', payload: { name: 'Bob', token: 'hat' } });
    expect(bob.statusCode).toBe(201);
    const res = await patch(a.id, { ownerId: bob.json().id });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toEqual({ ...a, ownerId: bob.json().id });
    const got = await app.inject({ method: 'GET', url: `/properties/${a.id}` });
    expect(got.json()).toEqual({ ...a, ownerId: bob.json().id, ownerName: 'Bob' });
  });

  it.each([
    ['empty name', { name: '' }],
    ['blank name', { name: '   ' }],
    ['41-character name', { name: 'a'.repeat(41) }],
    ['unknown colorGroup', { colorGroup: 'nope' }],
    ['price below 1', { price: 0 }],
    ['fractional price', { price: 1.5 }],
    ['price above 400', { price: 401 }],
    ['rent below 0', { rent: -1 }],
    ['fractional rent', { rent: 0.5 }],
    ['non-uuid ownerId', { ownerId: 'nope' }],
    ['unknown ownerId', { ownerId: UNKNOWN_ID }],
    ['unknown field', { nope: 1 }],
    ['empty body', {}],
  ])('rejects %s with 400', async (_, payload) => {
    const a = await createOk();
    expectError(await patch(a.id, payload), 400, 'invalid');
  });

  it('rejects a name taken by another property, in any case, with 409', async () => {
    await createOk(valid(1));
    const b = await createOk(valid(2));
    expectError(await patch(b.id, { name: 'Alpha' }), 409, 'conflict');
    expectError(await patch(b.id, { name: 'alpha' }), 409, 'conflict');
  });

  it('changes the case of its own name', async () => {
    const a = await createOk();
    expect((await patch(a.id, { name: 'ALPHA' })).json().name).toBe('ALPHA');
  });

  it('answers 404 for an unknown id', async () => {
    expectError(await patch(UNKNOWN_ID, { name: 'Bravo' }), 404, 'not_found');
  });

  it('answers 400 for a non-uuid id', async () => {
    expectError(await patch('nope', { name: 'Bravo' }), 400, 'invalid');
  });
});

describe('DELETE /properties/:id', () => {
  it('deletes the property', async () => {
    const a = await createOk();
    const res = await app.inject({ method: 'DELETE', url: `/properties/${a.id}` });
    expect(res.statusCode).toBe(204);
    expect(res.body).toBe('');
    expectError(await app.inject({ method: 'GET', url: `/properties/${a.id}` }), 404, 'not_found');
  });

  it('frees the name for reuse', async () => {
    const a = await createOk();
    await app.inject({ method: 'DELETE', url: `/properties/${a.id}` });
    await createOk();
  });

  it('answers 404 for an unknown id', async () => {
    expectError(await app.inject({ method: 'DELETE', url: `/properties/${UNKNOWN_ID}` }), 404, 'not_found');
  });

  it('answers 400 for a non-uuid id', async () => {
    expectError(await app.inject({ method: 'DELETE', url: '/properties/nope' }), 400, 'invalid');
  });
});
